//! Array lookups generated by oxyde-sql, executed through oxyde pools on
//! SQLite, where they depend on the `oxyde_array_match` function registered
//! by the pool's connect hook.

use std::collections::HashMap;
use std::time::Duration;

use oxyde_codec::{ColumnTypeSpec, Filter, FilterNode, Operation, QueryIR};
use oxyde_driver::{
    close_pool, execute_query_columnar, execute_statement, init_pool, PoolSettings,
};
use oxyde_sql::{build_sql, Dialect};
use uuid::Uuid;

fn decode_ids(buf: &[u8]) -> Vec<i64> {
    let val: rmpv::Value = rmp_serde::from_slice(buf).unwrap();
    val.as_array().unwrap()[1]
        .as_array()
        .unwrap()
        .iter()
        .map(|row| row.as_array().unwrap()[0].as_i64().unwrap())
        .collect()
}

fn array_of(item: ColumnTypeSpec) -> ColumnTypeSpec {
    ColumnTypeSpec::Array {
        item: Box::new(item),
    }
}

fn column_types() -> HashMap<String, ColumnTypeSpec> {
    HashMap::from([
        ("tags".to_string(), array_of(ColumnTypeSpec::Text)),
        (
            "amounts".to_string(),
            array_of(ColumnTypeSpec::Decimal {
                precision: Some(10),
                scale: Some(2),
            }),
        ),
        ("doc".to_string(), ColumnTypeSpec::Json),
    ])
}

fn s(v: &str) -> rmpv::Value {
    rmpv::Value::String(v.into())
}

fn arr(items: Vec<rmpv::Value>) -> rmpv::Value {
    rmpv::Value::Array(items)
}

fn map(pairs: Vec<(&str, rmpv::Value)>) -> rmpv::Value {
    rmpv::Value::Map(pairs.into_iter().map(|(k, v)| (s(k), v)).collect())
}

async fn insert(pool: &str, id: i64, tags: rmpv::Value, amounts: rmpv::Value, doc: rmpv::Value) {
    let ir = QueryIR {
        op: Operation::Insert,
        table: "items".into(),
        values: Some(HashMap::from([
            ("id".to_string(), rmpv::Value::Integer(id.into())),
            ("tags".to_string(), tags),
            ("amounts".to_string(), amounts),
            ("doc".to_string(), doc),
        ])),
        column_types: Some(column_types()),
        ..Default::default()
    };
    let (sql, params) = build_sql(&ir, Dialect::Sqlite).unwrap();
    execute_statement(pool, &sql, &params).await.unwrap();
}

fn condition(field: &str, operator: &str, value: rmpv::Value) -> FilterNode {
    FilterNode::Condition(Filter {
        field: field.into(),
        operator: operator.into(),
        value,
        column: None,
        escape: None,
        db_type: None,
    })
}

async fn select_ids(pool: &str, field: &str, operator: &str, value: rmpv::Value) -> Vec<i64> {
    select_ids_where(pool, condition(field, operator, value)).await
}

async fn select_ids_where(pool: &str, filter: FilterNode) -> Vec<i64> {
    let ir = QueryIR {
        op: Operation::Select,
        table: "items".into(),
        cols: Some(vec!["id".into()]),
        column_types: Some(column_types()),
        filter_tree: Some(filter),
        order_by: Some(vec![("id".into(), "ASC".into())]),
        ..Default::default()
    };
    let (sql, params) = build_sql(&ir, Dialect::Sqlite).unwrap();
    let (bytes, _) = execute_query_columnar(pool, &sql, &params, None)
        .await
        .unwrap();
    decode_ids(&bytes)
}

async fn setup(settings: PoolSettings) -> (String, tempfile::TempDir) {
    let dir = tempfile::tempdir().unwrap();
    let url = format!("sqlite://{}", dir.path().join("arrays.db").display());
    let pool = format!("arrays_{}", Uuid::new_v4().simple());
    init_pool(&pool, &url, settings).await.unwrap();
    execute_statement(
        &pool,
        "CREATE TABLE items (id INTEGER PRIMARY KEY, tags TEXT, amounts TEXT, doc TEXT)",
        &[],
    )
    .await
    .unwrap();

    insert(
        &pool,
        1,
        arr(vec![s("rust"), s("python")]),
        arr(vec![s("1.50"), s("2.00")]),
        arr(vec![map(vec![("a", 1.into()), ("b", 2.into())]), 1.into()]),
    )
    .await;
    insert(
        &pool,
        2,
        arr(vec![s("go"), rmpv::Value::Nil]),
        arr(vec![]),
        arr(vec![arr(vec![1.into(), 2.into()])]),
    )
    .await;
    insert(
        &pool,
        3,
        rmpv::Value::Nil,
        rmpv::Value::Nil,
        map(vec![("a", 1.into())]),
    )
    .await;
    (pool, dir)
}

#[tokio::test]
async fn sqlite_array_lookups_run_through_the_pool() {
    let (pool, _dir) = setup(PoolSettings::default()).await;

    assert_eq!(
        select_ids(&pool, "tags", "ARRAY_CONTAINS", arr(vec![s("rust")])).await,
        [1]
    );
    assert_eq!(
        select_ids(&pool, "tags", "ARRAY_CONTAINS", arr(vec![rmpv::Value::Nil])).await,
        [2]
    );
    assert_eq!(
        select_ids(
            &pool,
            "tags",
            "ARRAY_CONTAINED_BY",
            arr(vec![s("go"), rmpv::Value::Nil])
        )
        .await,
        [2]
    );
    assert_eq!(
        select_ids(
            &pool,
            "tags",
            "ARRAY_OVERLAP",
            arr(vec![s("go"), s("rust")])
        )
        .await,
        [1, 2]
    );
    // Typed decimals stored as "1.50" match an operand of 1.5.
    assert_eq!(
        select_ids(&pool, "amounts", "ARRAY_CONTAINS", arr(vec![s("1.5")])).await,
        [1]
    );
    assert_eq!(
        select_ids(&pool, "amounts", "ARRAY_CONTAINED_BY", arr(vec![])).await,
        [2]
    );
    // JSON objects compare whole, ignoring key order; non-arrays never match.
    assert_eq!(
        select_ids(
            &pool,
            "doc",
            "ARRAY_CONTAINS",
            arr(vec![map(vec![("b", 2.into()), ("a", 1.into())])])
        )
        .await,
        [1]
    );
    // A partial object is not an element of the array.
    let partial = arr(vec![map(vec![("a", 1.into())])]);
    assert_eq!(
        select_ids(&pool, "doc", "ARRAY_CONTAINS", partial).await,
        [] as [i64; 0]
    );
    assert_eq!(
        select_ids(
            &pool,
            "doc",
            "ARRAY_CONTAINS",
            arr(vec![arr(vec![1.into(), 2.into()])])
        )
        .await,
        [2]
    );

    close_pool(&pool).await.unwrap();
}

#[tokio::test]
async fn unreadable_stored_values_do_not_match() {
    let (pool, _dir) = setup(PoolSettings::default()).await;

    // A string that is not JSON is stored as is in a JSON column.
    insert(&pool, 4, rmpv::Value::Nil, rmpv::Value::Nil, s("hello")).await;
    // Valid JSON, but the exponent is beyond what the matcher normalizes.
    execute_statement(
        &pool,
        "INSERT INTO items (id, doc) VALUES (5, '[1, 1e99999999999999999999]')",
        &[],
    )
    .await
    .unwrap();

    assert_eq!(
        select_ids(&pool, "doc", "ARRAY_OVERLAP", arr(vec![1.into()])).await,
        [1, 5]
    );
    assert_eq!(
        select_ids(&pool, "doc", "ARRAY_CONTAINED_BY", arr(vec![s("hello")])).await,
        [] as [i64; 0]
    );

    close_pool(&pool).await.unwrap();
}

#[tokio::test]
async fn blob_values_do_not_fail_the_query_and_jsonb_matches() {
    let (pool, _dir) = setup(PoolSettings::default()).await;

    // Written by other SQLite clients: a BLOB that is not JSONB, and JSONB.
    execute_statement(&pool, "INSERT INTO items (id, doc) VALUES (4, X'FF')", &[])
        .await
        .unwrap();
    execute_statement(
        &pool,
        "INSERT INTO items (id, doc) VALUES (5, jsonb('[1, 2]'))",
        &[],
    )
    .await
    .unwrap();

    let one = || arr(vec![1.into()]);
    assert_eq!(
        select_ids(&pool, "doc", "ARRAY_CONTAINS", one()).await,
        [1, 5]
    );
    assert_eq!(
        select_ids(&pool, "doc", "ARRAY_OVERLAP", one()).await,
        [1, 5]
    );
    assert_eq!(
        select_ids(
            &pool,
            "doc",
            "ARRAY_CONTAINED_BY",
            arr(vec![1.into(), 2.into()])
        )
        .await,
        [5]
    );
    // The BLOB is a non-array like any other (false), so NOT keeps it.
    let not_contains = FilterNode::Not {
        condition: Box::new(condition("doc", "ARRAY_CONTAINS", one())),
    };
    assert_eq!(select_ids_where(&pool, not_contains).await, [2, 3, 4]);

    close_pool(&pool).await.unwrap();
}

#[tokio::test]
async fn like_on_json_columns_reads_jsonb_strings() {
    let (pool, _dir) = setup(PoolSettings::default()).await;

    // A JSON string as text and as JSONB, and text that is not JSON.
    execute_statement(
        &pool,
        "INSERT INTO items (id, doc) VALUES (4, '\"hello\"'), (5, jsonb('\"hello\"')), (6, 'hello'), \
         (7, jsonb('{\"k\":\"v\"}'))",
        &[],
    )
    .await
    .unwrap();

    assert_eq!(select_ids(&pool, "doc", "LIKE", s("hel%")).await, [4, 5, 6]);
    // Arrays and objects still match their JSON text, JSONB ones included.
    assert_eq!(select_ids(&pool, "doc", "LIKE", s("{%")).await, [3, 7]);
    assert_eq!(select_ids(&pool, "doc", "LIKE", s("%\"k\"%")).await, [7]);

    close_pool(&pool).await.unwrap();
}

#[tokio::test]
async fn function_is_registered_on_additional_and_replacement_connections() {
    let (pool, _dir) = setup(PoolSettings {
        max_connections: Some(4),
        min_connections: Some(4),
        max_lifetime: Some(Duration::from_millis(100)),
        ..Default::default()
    })
    .await;

    // Concurrent queries spread over every pooled connection.
    let queries = (0..8).map(|_| select_ids(&pool, "tags", "ARRAY_CONTAINS", arr(vec![s("rust")])));
    for ids in futures::future::join_all(queries).await {
        assert_eq!(ids, [1]);
    }

    // Connections past max_lifetime are closed and reopened through the hook.
    tokio::time::sleep(Duration::from_millis(300)).await;
    let queries = (0..8).map(|_| select_ids(&pool, "tags", "ARRAY_OVERLAP", arr(vec![s("go")])));
    for ids in futures::future::join_all(queries).await {
        assert_eq!(ids, [2]);
    }

    close_pool(&pool).await.unwrap();
}
